{%- doc -%}
  Accordion Custom Component

  Renders the accordion-custom custom element wrapper with co-located styles.

  @param {string} children - The content to render inside the component (typically a <details> element)
  @param {string} [class] - Additional CSS classes
  @param {boolean} [open] - Whether the accordion is open (marker attribute)
  @param {boolean} [open_by_default_on_desktop] - Whether accordion opens by default on desktop
  @param {boolean} [open_by_default_on_mobile] - Whether accordion opens by default on mobile
  @param {boolean} [disable_on_desktop] - Disables accordion behavior on desktop
  @param {boolean} [disable_on_mobile] - Disables accordion behavior on mobile
  @param {boolean} [disable_animation_on_desktop] - Disables animation on desktop (for horizontal filters)
  @param {boolean} [close_with_escape] - Enables closing with escape key
  @param {string} [data_filter_param_name] - Filter param name for facet identification

  @example
  {% capture accordion_content %}
    <details class="details">
      <summary>Click to expand</summary>
      <div class="details-content">Content here</div>
    </details>
  {% endcapture %}
  {% render 'accordion-custom-component',
    children: accordion_content,
    open_by_default_on_desktop: true
  %}
{%- enddoc -%}

{% render 'summary-icon-styles' %}

<accordion-custom
  {% if class %}
    class="{{ class }}"
  {% endif %}
  {% if open %}
    open
  {% endif %}
  {% if open_by_default_on_desktop %}
    open-by-default-on-desktop
  {% endif %}
  {% if open_by_default_on_mobile %}
    open-by-default-on-mobile
  {% endif %}
  {% if disable_on_desktop %}
    data-disable-on-desktop="true"
  {% endif %}
  {% if disable_on_mobile %}
    data-disable-on-mobile="true"
  {% endif %}
  {% if disable_animation_on_desktop %}
    data-disable-animation-on-desktop="true"
  {% endif %}
  {% if close_with_escape %}
    data-close-with-escape="true"
  {% endif %}
  {% if data_filter_param_name %}
    data-filter-param-name="{{ data_filter_param_name }}"
  {% endif %}
>
  {{ children }}
</accordion-custom>

{% stylesheet %}
  accordion-custom {
    details {
      &::details-content,
      .details-content {
        block-size: 0;
        overflow-y: clip;
        opacity: 0;
        interpolate-size: allow-keywords;
        transition: content-visibility var(--animation-speed-slow) allow-discrete,
          padding-block var(--animation-speed-slow) var(--animation-easing),
          opacity var(--animation-speed-slow) var(--animation-easing),
          block-size var(--animation-speed-slow) var(--animation-easing);
      }

      /* Disable transitions when the content toggle is not caused by the direct user interaction, e.g. opening the filters on mobile. */
      &:not(:focus-within)::details-content,
      &:not(:focus-within) .details-content {
        transition: none;
      }

      &:not([open]) {
        &::details-content,
        .details-content {
          padding-block: 0;
        }
      }

      &[open] {
        &::details-content,
        .details-content {
          opacity: 1;
          block-size: auto;

          @starting-style {
            block-size: 0;
            opacity: 0;
            overflow-y: clip;
          }

          &:focus-within {
            overflow-y: visible;
          }
        }
      }
    }
  }

  accordion-custom[data-disable-on-mobile='true'] summary {
    @media screen and (max-width: 749px) {
      cursor: auto;
    }
  }

  accordion-custom[data-disable-on-desktop='true'] summary {
    @media screen and (min-width: 750px) {
      cursor: auto;
    }
  }
{% endstylesheet %}

{%- doc -%}
  Styles for the accordion and accordion row components. Extracted into a
  snippet so that blocks which use accordion markup without nesting inside an
  accordion block (e.g. disclosures) can include these styles independently,
  ensuring they are sent to the client when CSS subsetting is enabled.
{%- enddoc -%}

{% stylesheet %}
  .accordion {
    flex: 1;
    width: 100%;
  }

  .accordion--dividers accordion-custom:not(:first-child) .details {
    border-block-start: var(--style-border-width) solid var(--color-border);
  }

  /* When accordion borders are not set, show fallback borders */
  .accordion--dividers {
    /* stylelint-disable-next-line declaration-property-value-disallowed-list */
    --show-fallback-borders: 0;
  }

  .accordion--dividers:not([class*='color-'])[style*='--border-width: 0'],
  .accordion--dividers:not([class*='color-'])[style*='--border-style: none'] {
    --show-fallback-borders: 1;
  }

  .accordion--dividers accordion-custom:first-child .details {
    border-block-start: calc(var(--style-border-width) * var(--show-fallback-borders)) solid var(--color-border);
  }

  .accordion--dividers accordion-custom:last-child .details {
    border-block-end: calc(var(--style-border-width) * var(--show-fallback-borders)) solid var(--color-border);
  }

  .accordion--dividers .details-content {
    padding-block-end: var(--padding-sm);
  }

  .accordion--caret .icon-plus,
  .accordion--plus .icon-caret {
    display: none;
  }

  /* because we can't pass apply a specific class on a block based on its parent block setting */
  .accordion .details__header {
    font-family: var(--summary-font-family);
    font-style: var(--summary-font-style);
    font-weight: var(--summary-font-weight);
    font-size: var(--summary-font-size);
    line-height: var(--summary-font-line-height);
    text-transform: var(--summary-font-case);
    min-height: var(--minimum-touch-target);
  }

  .details__icon {
    height: auto;
    margin-inline-end: var(--margin-xs);
  }
{% endstylesheet %}

{%- doc -%}
  Shared add-to-cart button styles used by product forms, quick add,
  and sticky add-to-cart.

  @example
  {% render 'add-to-cart-button-styles' %}
{%- enddoc -%}

{% stylesheet %}
  /* Add to cart button */
  .button[id^='BuyButtons-ProductSubmitButton-'] {
    position: relative;
    overflow: hidden;
  }

  .add-to-cart-button {
    --text-speed: 0.26;
    --base-delay: calc(var(--text-speed) * 0.25);
    --tick-speed: 0.1;
    --ring-speed: 0.2;
    --check-speed: 0.2;
    --burst-speed: 0.32;
    --step-delay: 3;
    --speed: 1;

    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--gap-2xs);
    user-select: none;
    transition-property: color, box-shadow, background-color, scale, translate;
    transition-duration: var(--animation-speed);
    transition-timing-function: var(--ease-out-cubic);

    &:active {
      scale: 0.99;
      translate: 0 1px;
    }
  }

  .add-to-cart-button .svg-wrapper .checkmark-burst {
    width: 30px;
    height: 30px;
  }

  .add-to-cart-text {
    --atc-opacity: 0;
    --atc-destination: -1em;

    display: flex;
    gap: var(--gap-2xs);
    align-items: center;
    justify-content: center;
    animation-duration: var(--animation-speed);
    animation-timing-function: var(--animation-easing);
    animation-fill-mode: forwards;
    transition: width var(--animation-speed) var(--animation-easing),
      opacity var(--animation-speed) var(--animation-easing);
  }

  .add-to-cart__added {
    --atc-opacity: 1;
    --atc-destination: 0px;

    position: absolute;
    top: 50%;
    left: 50%; /* stylelint-disable-line csstools/use-logical -- centring pair with a physical translate(-50%) */
    translate: -50% -50%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
  }

  .add-to-cart__added-icon {
    width: 32px;
    height: 32px;
  }

  [data-added='true'] .add-to-cart-text,
  [data-added='true'] .add-to-cart__added {
    animation-name: atc-slide;
  }

  .checkmark-burst {
    opacity: 0;
    overflow: visible;

    .burst {
      rotate: 20deg;
    }

    .check {
      opacity: 0.2;
      scale: 0.8;
      filter: blur(2px);
      transform: translateZ(0);
    }

    :is(.ring, .line, .check, .burst, .tick) {
      transform-box: fill-box;
      transform-origin: center;
    }

    :is(.line) {
      stroke-dasharray: 1.5 1.5;
      stroke-dashoffset: -1.5;
      translate: 0 -180%;
    }

    g {
      transform-origin: center;
      rotate: calc(var(--index) * (360 / 8) * 1deg);
    }
  }

  .add-to-cart-button[data-added='true'] .checkmark-burst {
    opacity: 1;
  }

  .add-to-cart-button[data-added='true'] {
    color: transparent;

    .check {
      opacity: 1;
      scale: 1;
      filter: blur(0);
    }

    .tick {
      scale: 1.75;
    }

    .ring {
      opacity: 0;
      scale: 1;
    }

    .line {
      stroke-dashoffset: 1.5;
    }

    .add-to-cart__added {
      color: var(--button-color);
    }

    .add-to-cart-text {
      /* stylelint-disable-next-line plugin/no-unsupported-browser-features */
      clip-path: circle(0% at 50% 50%);
      filter: blur(2px);
      opacity: 0;
      translate: 0 4px;
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .add-to-cart-button[data-added='true'] {
      .check {
        transition-property: opacity, scale, filter;
        transition-duration: calc(calc(var(--check-speed) * 1s));
        transition-delay: calc((var(--base-delay) * 1s));
        transition-timing-function: var(--ease-out-quad);
      }

      .tick {
        transition-property: scale;
        transition-duration: calc((calc(var(--tick-speed) * 1s)));
        transition-delay: calc(((var(--base-delay) + (var(--check-speed) * (var(--step-delay) * 1.1))) * 1s));
        transition-timing-function: ease-out;
      }

      .ring {
        transition-property: opacity, scale;
        transition-duration: calc((calc(var(--ring-speed) * 1s)));
        transition-delay: calc(((var(--base-delay) + (var(--check-speed) * var(--step-delay))) * 1s));
        transition-timing-function: var(--ease-out-quad);
      }

      .line {
        transition-property: stroke-dashoffset;
        transition-duration: calc((calc(var(--burst-speed) * 1s)));
        transition-delay: calc(((var(--base-delay) + (var(--check-speed) * var(--step-delay))) * 1s));
        transition-timing-function: var(--ease-out-cubic);
      }
    }

    .add-to-cart-text {
      transition-property: clip-path, opacity, filter, translate;
      transition-duration: calc((var(--text-speed) * 0.6s)), calc((var(--text-speed) * 1s));
      transition-timing-function: ease-out;
    }
  }

  .add-to-cart-text {
    /* stylelint-disable-next-line plugin/no-unsupported-browser-features */
    clip-path: circle(100% at 50% 50%);
  }

  @keyframes atc-slide {
    to {
      opacity: var(--atc-opacity, 1);
      translate: 0px var(--atc-destination, 0px);
    }
  }
{% endstylesheet %}

{%- doc -%}
  Renders an "Add to cart" button with dynamic text and state. It shows different text based on whether the product can be added to the cart and provides visual feedback when an item is added.

  @param {boolean} can_add_to_cart - Whether the product can be added to the cart.
  @param {string} add_to_cart_text - The text to display on the button.
  @param {object} product - The product object to be added to the cart.
  @param {boolean} show_icon - Whether to render the cart icon.
  @param {string} [class] - Additional CSS classes to apply to the button.
  @param {string} [id] - The ID attribute for the button.
  @param {string} [data_testid] - The data-testid attribute for testing.
{%- enddoc -%}

{%- liquid
  assign default_add_to_cart_text = 'actions.add_to_cart' | t
  assign product_variant_media = product.selected_or_first_available_variant.featured_media.preview_image | image_url: width: 100
  if product.selected_or_first_available_variant.featured_media.preview_image == blank
    assign product_variant_media = product.featured_media.preview_image | image_url: width: 100
  endif
-%}

<add-to-cart-component
  ref="addToCartButtonContainer"
  data-product-variant-media="{{ product_variant_media }}"
  data-add-to-cart-animation="{{ settings.add_to_cart_animation }}"
>
  <button
    {% if id != blank %}
      id="{{ id }}"
    {% endif %}
    type="submit"
    name="add"
    ref="addToCartButton"
    on:click="/handleClick"
    class="button {{ class }}"
    {% if data_testid %}
      data-testid="{{ data_testid }}"
    {% endif %}
    {% unless can_add_to_cart %}
      disabled
    {% endunless %}
  >
    {% if show_icon %}
      <span
        aria-hidden="true"
        class="svg-wrapper add-to-cart-icon"
      >
        {{- 'icon-add-to-cart.svg' | inline_asset_content -}}
      </span>
    {% endif %}
    {{- add_to_cart_text | default: default_add_to_cart_text -}}
    {% comment %} checkmark burst markup {% endcomment %}
    <span class="add-to-cart__added">
      <span class="svg-wrapper add-to-cart__added-icon">
        {{- 'icon-checkmark-burst.svg' | inline_asset_content -}}
      </span>
    </span>
  </button>
</add-to-cart-component>

{%- doc -%}
  Renders a background media

  @param {string} [background_media] - The background media
  @param {object} [background_video] - The background video
  @param {string} [background_video_position] - The background video position
  @param {object} [background_image] - The background image
  @param {string} [background_image_position] - The background image position
  @param {string} [placeholder] - The placeholder
  @param {object} [block] - The block object
  @param {object} [section] - The section object

  @example
  {% render 'background-media', background_media: background_media, background_video: background_video, background_video_position: background_video_position, background_image: background_image, background_image_position: background_image_position, placeholder: placeholder %}
{%- enddoc -%}

{% if background_media == 'video' %}
  {% liquid
    assign video_classes = 'video-background video-background--' | append: background_video_position
  %}
  {%- if background_video != blank -%}
    <video-background-component
      class="{{ video_classes }}"
    >
      {% liquid
        assign media_width_desktop = 100 | append: 'vw'
        assign media_width_mobile = '100vw'
        assign sizes = '(min-width: 750px) ' | append: media_width_desktop | append: ', ' | append: media_width_mobile
        assign widths = '240, 352, 832, 1200, 1600, 1920, 2560, 3840'
        assign video_fetch_priority = 'auto'
        assign video_loading = 'eager'

        if section and section.index == 1
          assign video_fetch_priority = 'high'
        endif

        if section and section.index > 3
          assign video_loading = 'lazy'
        endif
      %}
      {{
        background_video.preview_image
        | image_url: width: 3840
        | image_tag:
          width: 1100,
          widths: widths,
          sizes: sizes,
          loading: video_loading,
          fetchpriority: video_fetch_priority
      }}
      <video
        playsinline
        muted
        autoplay
        loop
        ref="videoElement"
      >
        {%- for sourceElement in background_video.sources -%}
          <source
            data-video-source="{{ sourceElement.url }}"
            type="{{ sourceElement.mime_type }}"
            ref="videoSources[]"
          >
        {%- endfor -%}
      </video>
    </video-background-component>
  {%- else -%}
    <div class="{{ video_classes }}">
      {%- assign placeholder_name = placeholder | default: 'hero-apparel-2' -%}
      {%- if placeholder_name == blank -%}
        {%- assign placeholder_name = 'hero-apparel-2' -%}
      {%- endif -%}
      {{ placeholder_name | placeholder_svg_tag }}
    </div>
  {%- endif -%}
{% elsif background_media == 'image' %}
  <div
    class="background-image-container{% if background_image_position == 'fit' %} background-image-fit{% endif %}"
  >
    {% liquid
      # Define sizes based on page width setting whether this is called from a section or block

      if block.settings
        if section.settings.section_width == 'full-width'
          assign sizes = '100vw'
        else
          case settings.page_width
            when 'narrow'
              # Narrow: max 90rem (1440px)
              assign sizes = '(min-width: 1440px) 1440px, 100vw'
            when 'normal'
              # Normal: max 120rem (1920px)
              assign sizes = '(min-width: 1920px) 1920px, 100vw'
            when 'wide'
              # Wide: max 150rem (2400px)
              assign sizes = '(min-width: 2400px) 2400px, 100vw'
            else
              # Fallback to full width
              assign sizes = '100vw'
          endcase
        endif
      else
        assign sizes = '100vw'
      endif

      assign widths = '832, 1200, 1600, 1920, 2560, 3840'
    %}

    {%- if background_image != blank -%}
      {% liquid
        assign fetch_priority = 'auto'
        assign loading = 'eager'
        if section and section.index == 1
          assign fetch_priority = 'high'
        endif

        if section and section.index > 3
          assign loading = 'lazy'
        endif
      %}
      {{
        background_image
        | image_url: width: 3840
        | image_tag: sizes: sizes, widths: widths, loading: loading, fetchpriority: fetch_priority
      }}
    {%- else -%}
      {%- assign placeholder_name = placeholder | default: 'hero-apparel-2' -%}
      {%- if placeholder_name == blank -%}
        {%- assign placeholder_name = 'hero-apparel-2' -%}
      {%- endif -%}
      {{ placeholder_name | placeholder_svg_tag }}
    {%- endif -%}
  </div>
{% endif %}

{% render 'video-background-styles' %}

{% stylesheet %}
  .background-image-container {
    overflow: hidden;
    position: absolute;
    inset: 0;
    opacity: var(--image-opacity);
  }

  .background-image-container img,
  .background-image-container svg {
    object-fit: cover;
    width: 100%;
    height: 100%;
  }

  .background-image-fit img,
  .background-image-fit svg {
    object-fit: contain;
  }
{% endstylesheet %}

{%- doc -%}
  Takes an array of HTML strings and positions them in a bento box grid layout.
  Bento boxes can hold up to 12 items; when more items are provided, a new box is created to maintain the layout structure.

  @param {string[]} items - An array of HTML strings, where each string is a collection list item.
{%- enddoc -%}

{% liquid
  assign odd_item_check = items.size | modulo: 12
  if odd_item_check == 1
    assign first_box_size = 11
  else
    assign first_box_size = 12
  endif
%}

{% for item in items %}
  {% liquid
    if first_box_size == 11
      assign item_modulo = forloop.index | modulo: 11
      if forloop.index == 12
        # Close the box and for a new one to start
        assign item_modulo = forloop.index | modulo: 12
        assign item_modulo = 1
      endif
    else
      assign item_modulo = forloop.index | modulo: 12
    endif

    # Calculate items in current box when starting a new box
    if forloop.first or item_modulo == 1
      assign remaining_items = items.size | minus: forloop.index0
      if remaining_items >= first_box_size
        assign box_item_count = first_box_size
      else
        assign box_item_count = remaining_items
      endif
    endif
  %}

  {% if forloop.first or item_modulo == 1 %}
    <div
      class="bento-box bento-box--items-{{ box_item_count }}"
      data-testid="bento-box"
    >
  {% endif %}

  <div class="bento-box__item">
    {{ item }}
  </div>

  {% if forloop.last or item_modulo == 0 %}
    </div>
  {% endif %}
{% endfor %}

{% stylesheet %}
  .bento-box {
    display: grid;
    column-gap: var(--bento-gap);
    row-gap: calc(var(--bento-gap) * 1.5);
    width: 100%;
  }

  .bento-box:has(.collection-card--image-bg) {
    row-gap: var(--bento-gap);
  }

  .bento-box ~ .bento-box {
    padding-block-start: var(--bento-gap);
  }

  @media screen and (max-width: 900px) {
    .bento-box {
      grid-template-columns: repeat(2, 1fr);
    }

    .bento-box__item {
      /* Prevent grid items from overflowing their cells when children have aspect-ratio */
      min-width: 0;
      overflow: hidden;
    }

    .bento-box__item:nth-child(3n + 1) {
      grid-column: span 1;
    }

    .bento-box__item:nth-child(3n + 2) {
      grid-column: span 1;
    }

    .bento-box__item:nth-child(3n + 3) {
      grid-column: span 2;
    }

    /* Ensure last items create a full row */
    .bento-box__item:last-child:nth-child(3n + 5) {
      grid-column: span 1;
    }

    .bento-box__item:last-child:nth-child(3n + 4) {
      grid-column: span 2;
    }
  }

  @media screen and (min-width: 901px) {
    .bento-box {
      grid-template-columns: repeat(12, 1fr);
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D E E E F F F'
        'G G G H H H I I I I I I'
        'J J J J K K K K L L L L';
    }

    .bento-box__item:nth-child(1) {
      grid-area: A;
    }

    .bento-box__item:nth-child(2) {
      grid-area: B;
    }

    .bento-box__item:nth-child(3) {
      grid-area: C;
    }

    .bento-box__item:nth-child(4) {
      grid-area: D;
    }

    .bento-box__item:nth-child(5) {
      grid-area: E;
    }

    .bento-box__item:nth-child(6) {
      grid-area: F;
    }

    .bento-box__item:nth-child(7) {
      grid-area: G;
    }

    .bento-box__item:nth-child(8) {
      grid-area: H;
    }

    .bento-box__item:nth-child(9) {
      grid-area: I;
    }

    .bento-box__item:nth-child(10) {
      grid-area: J;
    }

    .bento-box__item:nth-child(11) {
      grid-area: K;
    }

    .bento-box__item:nth-child(12) {
      grid-area: L;
    }

    /* === Overrides for specific item counts === */

    /* Exactly 1 item */
    .bento-box--items-1 {
      grid-template-areas: 'A A A A A A A A A A A A';
    }

    /* Exactly 2 items */
    .bento-box--items-2 {
      grid-template-areas: 'A A A A A A B B B B B B';
    }

    /* Exactly 4 items */
    .bento-box--items-4 {
      grid-template-areas:
        'A A A A B B B B B B B B'
        'C C C C C C C C D D D D';
    }

    /* Exactly 5 items */
    .bento-box--items-5 {
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D E E E E E E';
    }

    /* Exactly 7 items */
    .bento-box--items-7 {
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D D D D E E E'
        'F F F F F F G G G G G G';
    }

    /* Exactly 8 items */
    .bento-box--items-8 {
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D E E E F F F'
        'G G G H H H H H H H H H';
    }

    /* Exactly 10 items */
    .bento-box--items-10 {
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D E E E F F F'
        'G G G G G G G G G H H H'
        'I I I J J J J J J J J J';
    }

    /* Exactly 11 items */
    .bento-box--items-11 {
      grid-template-areas:
        'A A A B B B B B B C C C'
        'D D D D D D E E E F F F'
        'G G G H H H I I I I I I'
        'J J J J K K K K K K K K';
    }
  }
{% endstylesheet %}

{%- doc -%}
  Renders a comment form for a blog post.

  @param {object} [form] - The form object
  @param {object} [article] - The article object
  @param {comment} [comment] - The comment object
  @param {string} [section_id] - The section ID
{%- enddoc -%}

{% form 'new_comment', article %}
  <div class="blog-post-comments__form-container">
    <h2 class="h3">{{- 'blogs.comment_form.heading' | t -}}</h2>

    {%- if form.errors -%}
      <p
        class="blog-post-comments__form-message"
        role="alert"
      >
        {{- 'icon-error.svg' | inline_asset_content -}}

        {{- 'blogs.comment_form.error' | t -}}
      </p>

      <ul class="">
        {%- for field in form.errors -%}
          <li>
            {%- if form.errors.translated_fields[field] contains 'author' -%}
              <span id="blog-post-comment-author-error">
                {{- 'blogs.comment_form.name' | t -}}
              </span>
            {%- elsif form.errors.translated_fields[field] contains 'body' -%}
              <span id="blog-post-comment-body-error">
                {{- 'blogs.comment_form.message' | t -}}
              </span>
            {%- else -%}
              <span id="{{ form.errors.translated_fields[field] | handleize }}-error">
                {{- form.errors.translated_fields[field] | capitalize -}}
              </span>
            {%- endif -%}
            {{ form.errors.messages[field] }}
          </li>
        {%- endfor -%}
      </ul>
    {%- elsif form.posted_successfully? -%}
      <p
        class="blog-post-comments__form-message"
        role="alert"
      >
        {{- 'icon-checkmark.svg' | inline_asset_content -}}

        {%- liquid
          assign post_message = 'blogs.comment_form.success'
          if blog.moderated? and comment.status == 'unapproved'
            assign post_message = 'blogs.comment_form.success_moderated'
          endif
        -%}

        {{ post_message | t }}
      </p>
    {%- endif -%}

    <div class="blog-post-comments__form">
      <div class="field">
        <label
          class="visually-hidden"
          for="{{ section_id }}-blog-post-comment-author"
        >
          {{ 'blogs.comment_form.name' | t }}
        </label>

        <input
          type="text"
          name="comment[author]"
          id="{{ section_id }}-blog-post-comment-author"
          class="blog-post-comments__form-input field__input"
          autocomplete="name"
          value="{{- form.author -}}"
          aria-required="true"
          placeholder="{{ 'blogs.comment_form.name' | t }}"
          required
          {% if form.errors contains 'author' %}
            aria-invalid="true"
            aria-describedby="blog-post-comment-author-error"
          {% endif %}
        >
      </div>

      <div class="field">
        <label
          class="visually-hidden"
          for="{{ section_id }}-blog-post-comment-email"
        >
          {{ 'blogs.comment_form.email' | t }}
        </label>

        <input
          type="email"
          name="comment[email]"
          id="{{ section_id }}-blog-post-comment-email"
          autocomplete="email"
          class="blog-post-comments__form-input field__input"
          value="{{ form.email }}"
          autocorrect="off"
          autocapitalize="off"
          aria-required="true"
          placeholder="{{ 'blogs.comment_form.email' | t }}"
          required
          {% if form.errors contains 'email' %}
            aria-invalid="true"
            aria-describedby="blog-post-comment-email-error"
          {% endif %}
        >
      </div>

      <div class="field blog-post-comments__form-body">
        <label
          class="visually-hidden"
          for="{{ section_id }}-blog-post-comment-body"
        >
          {{ 'blogs.comment_form.message' | t }}
        </label>

        <textarea
          rows="5"
          name="comment[body]"
          id="{{ section_id }}-blog-post-comment-body"
          class="blog-post-comments__form-input blog-post-comments__form-input--textarea field__input"
          aria-required="true"
          placeholder="{{ 'blogs.comment_form.message' | t }}"
          required
          {% if form.errors contains 'body' %}
            aria-invalid="true"
            aria-describedby="blog-post-comment-body-error"
          {% endif %}
        >
          {{- form.body -}}
        </textarea>
      </div>
    </div>

    {% if blog.moderated? %}
      <p class="blog-post-comments__form-moderated">
        {{- 'blogs.comment_form.moderated' | t -}}
      </p>
    {% endif %}

    <button
      class="button blog-post-comments__form-submit"
      type="submit"
    >
      {{ 'blogs.comment_form.post' | t }}
    </button>
  </div>
{% endform %}

{% stylesheet %}
